output_text:
[
  {
    "id": "no_cart_single_file_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_pushing_cart_into_single_file",
    "text": "A shopper may not push a cart from a wider aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or releases a cart, they are obliged to retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "wideAisle"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "cart_transfers_only_in_wide_aisles",
    "text": "Cart pickup and cart parking interactions should only occur in wide aisles where there is room to stand aside.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "dropCart",
              "pickUpCart"
            ]
          },
          {
            "not": "wideAisle"
          }
        ]
      }
    }
  },
  {
    "id": "interact_only_at_service_points",
    "text": "Interactions are allowed only at a service point: a shelf face, the cart bay, or a cart being picked up or parked.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "shelfFace": "adjShelf"
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": {
              "or": [
                "cartBay",
                "shelfFace",
                "dropCart",
                "pickUpCart"
              ]
            }
          }
        ]
      }
    }
  },
  {
    "id": "cart_shelf_interactions_need_adjacent_shelf",
    "text": "When interacting while still holding the cart, the shopper must be at some adjacent shelf face rather than at a fixed coarse item cell.",
    "abstraction": {
      "state_properties": {
        "adjacentShelfFace": "adjShelf"
      },
      "events": {
        "cartRetainedInteraction": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartRetainedInteraction",
          {
            "not": "adjacentShelfFace"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_entry_requires_shelf_task",
    "text": "Entering a single-file shelf aisle without a cart obliges the shopper to perform a shelf interaction there.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "not": "singleFileShelfAisle"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileWithoutCart",
      "discharge": {
        "and": [
          "singleFileShelfAisle",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "rejoin_cart_after_handcarry_aisle",
    "text": "After leaving a single-file shelf aisle without a cart, the shopper is obliged to rejoin the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "leaveSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "not": "singleFileShelfAisle"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveSingleFileWithoutCart",
      "discharge": "hasCart"
    }
  }
]
